const HEAD = 'extends SceneTree\n\nvar ga: Array = [1]\nvar gd: Dictionary = {"x": 1}\nvar gs: String = "abcd"\nvar gn: StringName = &"abcd"\nvar gnp: NodePath = ^"a/b"\nvar gc: Color = Color(1, 0, 0, 1)\nvar gv2: Vector2 = Vector2(1, 2)\nvar gv2i: Vector2i = Vector2i(1, 2)\nvar gv3: Vector3 = Vector3(1, 2, 3)\nvar gv3i: Vector3i = Vector3i(1, 2, 3)\n';

async function msgs(expr: string): Promise<string[]> {
  const src = HEAD + "func c():\n\tprint(" + expr + ")\n";
  return analyze(lower(await parseSource(src))).diagnostics.map((d) => d.message).sort();
}

